import Gio from 'gi://Gio';
import GLib from 'gi://GLib';
import Meta from 'gi://Meta';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';

// Only GNOME 45–48 need these (to filter the overview). Imported lazily so that a later GNOME that
// renames them cannot stop the extension from loading.
async function loadShellModules() {
    const load = name => import(`resource:///org/gnome/shell/ui/${name}.js`).catch(() => null);
    return {
        workspace: await load('workspace'),
        workspaceThumbnail: await load('workspaceThumbnail'),
    };
}

/* @@KABEGAME_CORE@@ */

export default class KabegameShellExtension extends Extension {
    enable() {
        this._kabegame = new KabegameExtension();
        this._kabegame.enable();
    }

    disable() {
        this._kabegame?.disable();
        this._kabegame = null;
    }
}
